// ============================================================
// CTE Automated Scheduling System — Frontend (app.js)
// API-driven, session-authenticated, responsive.
// ============================================================
const API = '/api';

// Academic Rank → Salary Grade mapping
const RANK_SG = {
  'Instructor I': 12, 'Instructor II': 13, 'Instructor III': 14,
  'Assistant Professor I': 15, 'Assistant Professor II': 16,
  'Assistant Professor III': 17, 'Assistant Professor IV': 18,
  'Associate Professor I': 19, 'Associate Professor II': 20,
  'Associate Professor III': 21, 'Associate Professor IV': 22,
  'Associate Professor V': 23,
  'Professor I': 24, 'Professor II': 25, 'Professor III': 26,
  'Professor IV': 27, 'Professor V': 28, 'Professor VI': 29,
  'University Professor': 30
};
function autoSG(rankId, sgId){
  const rankEl = document.getElementById(rankId);
  const sgEl   = document.getElementById(sgId);
  if(!rankEl || !sgEl) return;
  const sg = RANK_SG[rankEl.value];
  if(sg) sgEl.value = sg;
  else sgEl.value = '';
}

let STATE = {
  majors:[], rooms:[], dayClusters:[], timeslots:[],
  instructors:[], subjects:[], schedules:[],
  settings:{academic_year:'2025-2026', semester:'1st Semester'}
};

// ============================================================
// UTILITIES
// ============================================================
function escHtml(s){
  if(s==null)return'';
  return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function escAttr(s){return escHtml(s);}

async function apiReq(method,path,body){
  const opts={method,headers:{'Content-Type':'application/json'}};
  if(body!==undefined)opts.body=JSON.stringify(body);
  const res=await fetch(API+path,opts);
  let data;try{data=await res.json();}catch(e){data={};}
  if(res.status===401){showAuthScreen();throw new Error('Session expired. Please log in again.');}
  if(!res.ok)throw new Error(data.error||`Request failed (${res.status})`);
  return data;
}
const apiGet=p=>apiReq('GET',p);
const apiPost=(p,b)=>apiReq('POST',p,b);
const apiPut=async(path,body)=>{
  const res=await fetch(API+path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  let data;try{data=await res.json();}catch(e){data={};}
  if(res.status===401){showAuthScreen();throw new Error('Session expired.');}
  if(!res.ok)throw new Error(data.error||`Request failed (${res.status})`);
  return data;
};
const apiDelete=p=>apiReq('DELETE',p);

// ============================================================
// CONNECTION STATUS
// ============================================================
function setConn(online){
  const b=document.getElementById('conn-status');
  const t=document.getElementById('conn-status-text');
  b.className='conn-status '+(online?'online':'offline');
  t.textContent=online?'Connected':'Offline';
}

// ============================================================
// SHOW / HIDE PASSWORD TOGGLE
// ============================================================
function togglePwd(inputId, btn) {
  const input = document.getElementById(inputId);
  const isHidden = input.type === 'password';
  input.type = isHidden ? 'text' : 'password';
  btn.textContent = isHidden ? '🙈' : '👁';
  btn.title = isHidden ? 'Hide password' : 'Show password';
}

// ============================================================
// WORKLOAD CHECKBOX TOGGLE
// Clicking any checkbox on a workload card switches the checked mark
// (radio-style — only one checked at a time per card).
// If Service Credit is selected, the signature block switches to show
// VP for Academic Affairs under Recommending Approval + President as Approved.
// ============================================================
// Recomputes a workload card's "Total No. of Units" whenever the
// Add. Designation or Add. Special Assignment cells are hand-edited.
// Recomputes "No. of Units" as the live sum of every subject row's Units
// cell (including the blank adjustment row), then cascades into Total.
// Runs whenever a subject's Units value is hand-edited.
function wlRecalcUnitsSum(cardId){
  const unitsEl=document.getElementById(cardId+'-units');
  if(!unitsEl)return;
  const cells=document.querySelectorAll('.wl-unit-cell-'+cardId);
  let sum=0;
  cells.forEach(c=>{ const v=parseFloat(c.textContent); if(!isNaN(v))sum+=v; });
  unitsEl.textContent=(Math.round(sum*100)/100);
  wlRecalcTotal(cardId);
}

function wlRecalcTotal(cardId){
  const totalEl=document.getElementById(cardId+'-total');
  if(!totalEl)return;
  const unitsEl=document.getElementById(cardId+'-units');
  const base=parseFloat(unitsEl?.textContent)||parseFloat(totalEl.dataset.base)||0;
  const desig=parseFloat(document.getElementById(cardId+'-desig')?.textContent)||0;
  const special=parseFloat(document.getElementById(cardId+'-special')?.textContent)||0;
  totalEl.textContent=base+desig+special;
}

function wlToggle(el){
  const val    = el.dataset.val;
  const cardId = el.dataset.card;
  const card   = document.getElementById(cardId);

  // Only Service Credit checkbox is interactive; others are display-only
  if(val !== 'Service Credit') return;

  // SC checkbox on original card: NEVER checks itself — just creates/removes SC page
  const scPageId = cardId + '-sc-page';
  const existing = document.getElementById(scPageId);
  if(existing){
    existing.remove();
    return;
  }

  // Get instructor name from original card
  const name = card ? (card.querySelector('input.sign-line').value || '') : '';

  // Build Service Credit signature block (3-col recommending + President)
  // Uses the same row-based grid pattern as the normal workload signature
  // block so every column/row lines up cleanly instead of stacking loosely.
  const scSigsHtml = `
    <!-- Row 1: Prepared by | Conformed by | Verified by -->
    <div class="wl-sig-row">
      <div class="wl-sig-cell">
        <div class="wl-sig-label">Prepared by:</div>
        <input class="sign-line" value="" placeholder="Department Dean / Name">
        <div class="sign-role" contenteditable="true" style="outline:none;">Department Dean</div>
      </div>
      <div class="wl-sig-cell">
        <div class="wl-sig-label">Conformed by:</div>
        <input class="sign-line" value="${name}" style="text-transform:uppercase;">
        <div class="sign-role" contenteditable="true" style="outline:none;">Faculty</div>
      </div>
      <div class="wl-sig-cell">
        <div class="wl-sig-label">Verified by:</div>
        <input class="sign-line" value="" placeholder="Registrar">
        <div class="sign-role">Registrar</div>
      </div>
    </div>

    <!-- Row 2: Recommending Approval — Campus Director | VP for Academic Affairs | Dean, all in one row -->
    <div>
      <div class="wl-sig-block-label">Recommending Approval:</div>
      <div class="wl-sig-row">
        <div class="wl-sig-cell">
          <input class="sign-line" value="" placeholder="Campus Director">
          <div class="sign-role">Campus Director</div>
        </div>
        <div class="wl-sig-cell">
          <input class="sign-line" value="" placeholder="VP for Academic Affairs">
          <div class="sign-role">Vice President for Academic Affairs</div>
        </div>
        <div class="wl-sig-cell">
          <input class="sign-line" value="" placeholder="Dean, College of Teacher Education">
          <div class="sign-role">Dean, College of Teacher Education</div>
        </div>
      </div>
    </div>

    <!-- Row 3: Approved -->
    <div class="wl-sig-approved">
      <div class="wl-sig-label">Approved:</div>
      <input class="sign-line" value="" placeholder="University President">
      <div class="sign-role">President</div>
    </div>`;

  // Clone the original card's innerHTML as base for SC card
  const scPage = document.createElement('div');
  scPage.id        = scPageId;
  // Ensure SC checkbox on ORIGINAL card is always empty (it never checks itself)
  const origScCb = card.querySelector('.wl-cb[data-val="Service Credit"]');
  if(origScCb) origScCb.innerHTML = '';

  scPage.className = 'workload-card';
  scPage.innerHTML = card.innerHTML;

  // Fix cloned IDs so they don't conflict
  scPage.querySelectorAll('[id]').forEach(node => {
    node.id = node.id.replace(cardId, scPageId);
  });
  scPage.querySelectorAll('[data-card]').forEach(node => {
    node.dataset.card = scPageId;
  });

  // In SC page: clear ALL checkboxes (both static .wl-checkbox and clickable .wl-cb)
  scPage.querySelectorAll('.wl-checkbox, .wl-cb').forEach(cb => cb.innerHTML = '');
  // Then check only Service Credit
  const scCb = scPage.querySelector('.wl-cb[data-val="Service Credit"]');
  if(scCb) scCb.innerHTML = '<span class="wl-check">✓</span>';

  // Replace signature block with SC version (3-col)
  const scSigsEl = scPage.querySelector('.wl-sigs');
  if(scSigsEl){
    scSigsEl.className = 'wl-sigs wl-sigs-3col';
    scSigsEl.innerHTML = scSigsHtml;
  }

  // Make all table data cells in SC page editable
  scPage.querySelectorAll('table tbody td').forEach(td => {
    if(!td.querySelector('input') && !td.querySelector('span.wl-check')){
      td.setAttribute('contenteditable','true');
      td.style.outline = 'none';
      td.style.cursor  = 'text';
    }
  });

  // Insert after original card and scroll to it
  card.parentNode.insertBefore(scPage, card.nextSibling);
  scPage.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// ============================================================
// AUTH FLOW
// ============================================================
async function initAuth(){
  try{
    const st=await fetch(API+'/auth/status').then(r=>r.json());
    if(!st.setup){
      // First time — show setup form
      document.getElementById('auth-login-box').style.display='none';
      document.getElementById('auth-setup-box').style.display='block';
      showAuthScreen();
    } else if(!st.logged_in){
      document.getElementById('auth-login-box').style.display='block';
      document.getElementById('auth-setup-box').style.display='none';
      showAuthScreen();
    } else {
      hideAuthScreen();
      await loadState();
      renderAll();
    }
  }catch(e){
    setConn(false);
    showAuthScreen();
  }
}

function showAuthScreen(){document.getElementById('auth-screen').classList.add('show');}
function hideAuthScreen(){document.getElementById('auth-screen').classList.remove('show');}

async function doSetup(){
  const username=document.getElementById('setup-username').value.trim();
  const password=document.getElementById('setup-password').value;
  const confirm =document.getElementById('setup-confirm').value;
  const errEl=document.getElementById('setup-err');
  errEl.style.display='none';
  if(!username){errEl.textContent='Username is required.';errEl.style.display='block';return;}
  if(password.length<6){errEl.textContent='Password must be at least 6 characters.';errEl.style.display='block';return;}
  if(password!==confirm){errEl.textContent='Passwords do not match.';errEl.style.display='block';return;}
  try{
    await apiPost('/auth/setup',{username,password});
    hideAuthScreen();
    document.getElementById('topbar-username').textContent=username;
    await loadState();renderAll();
  }catch(e){errEl.textContent=e.message;errEl.style.display='block';}
}

async function doLogin(){
  const username=document.getElementById('login-username').value.trim();
  const password=document.getElementById('login-password').value;
  const errEl=document.getElementById('login-err');
  errEl.style.display='none';
  if(!username||!password){errEl.textContent='Enter username and password.';errEl.style.display='block';return;}
  try{
    await apiPost('/auth/login',{username,password});
    hideAuthScreen();
    document.getElementById('topbar-username').textContent=username;
    await loadState();renderAll();
  }catch(e){errEl.textContent=e.message;errEl.style.display='block';}
}

async function doLogout(){
  if(!confirm('Log out of the scheduling system?'))return;
  try{await apiPost('/auth/logout');}catch(e){}
  showAuthScreen();
  document.getElementById('auth-login-box').style.display='block';
  document.getElementById('auth-setup-box').style.display='none';
  document.getElementById('login-password').value='';
  document.getElementById('login-err').style.display='none';
}

async function changePassword(){
  const username    =document.getElementById('pwd-username').value.trim();
  const cur_pass    =document.getElementById('pwd-current').value;
  const new_pass    =document.getElementById('pwd-new').value;
  const errEl=document.getElementById('pwd-err');
  const okEl =document.getElementById('pwd-ok');
  errEl.style.display='none';okEl.style.display='none';
  if(!cur_pass){errEl.textContent='Enter your current password.';errEl.style.display='block';return;}
  if(!new_pass||new_pass.length<6){errEl.textContent='New password must be at least 6 characters.';errEl.style.display='block';return;}
  try{
    await apiPost('/auth/change-password',{username:username||undefined,current_password:cur_pass,new_password:new_pass});
    ['pwd-username','pwd-current','pwd-new'].forEach(id=>document.getElementById(id).value='');
    okEl.style.display='block';
    if(username)document.getElementById('topbar-username').textContent=username;
  }catch(e){errEl.textContent=e.message;errEl.style.display='block';}
}

// ============================================================
// RESPONSIVE — MOBILE HAMBURGER
// ============================================================
function toggleSidebar(){
  const sb=document.getElementById('sidebar');
  const ov=document.getElementById('overlay');
  const open=sb.classList.toggle('open');
  ov.classList.toggle('show',open);
}
function closeSidebar(){
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('overlay').classList.remove('show');
}
// Close sidebar when a tab is clicked on mobile
document.querySelectorAll('.tab-btn').forEach(b=>b.addEventListener('click',()=>{
  if(window.innerWidth<=640)closeSidebar();
}));

// ============================================================
// LOAD STATE
// ============================================================
async function loadState(){instColorClear&&instColorClear();
  try{
    const [majors,rooms,dayClusters,timeslots,instructors,subjects,schedules,settings]=await Promise.all([
      apiGet('/majors'),apiGet('/rooms'),apiGet('/day-clusters'),apiGet('/timeslots'),
      apiGet('/instructors'),apiGet('/subjects'),apiGet('/schedules'),apiGet('/settings')
    ]);
    STATE={majors,rooms,dayClusters,timeslots,instructors,subjects,schedules,settings};
    const acYearEl=document.getElementById('ac-year'), acSemEl=document.getElementById('ac-semester');
    if(acYearEl)acYearEl.value=settings.academic_year||'2025-2026';
    if(acSemEl)acSemEl.value=settings.semester||'1st Semester';
    setConn(true);
  }catch(e){
    setConn(false);
    if(!e.message.includes('Session'))showMsg(e.message,false);
  }
}

// Saves the global Academic Year + Semester (Manage Data section) so it can
// auto-fill on the Class Program and Faculty Workload documents.
async function saveAcademicSettings(){
  const academic_year=document.getElementById('ac-year').value.trim();
  const semester=document.getElementById('ac-semester').value;
  const err=document.getElementById('ac-err'), ok=document.getElementById('ac-ok');
  err.style.display='none';ok.style.display='none';
  if(!academic_year){err.textContent='Academic Year is required.';err.style.display='block';return;}
  try{
    const updated=await apiPut('/settings',{academic_year,semester});
    STATE.settings=updated;
    ok.style.display='block';
    setTimeout(()=>ok.style.display='none',2500);
  }catch(e){err.textContent=e.message;err.style.display='block';}
}

// ============================================================
// HELPERS
// ============================================================
function getInst(id){return STATE.instructors.find(i=>i.id===id);}
function getRoom(id){return STATE.rooms.find(r=>r.id===id);}
// Dynamic unique color per instructor — uses golden ratio hue spacing, never repeats
const _instColorCache={};
function instColor(id){
  if(!_instColorCache[id]){
    const idx=STATE.instructors.findIndex(x=>x.id===id);
    const hue=Math.round((idx*137.508)%360); // golden angle — maximally spread
    _instColorCache[id]=`hsl(${hue},60%,88%)`;
  }
  return _instColorCache[id];
}
function instColorClear(){Object.keys(_instColorCache).forEach(k=>delete _instColorCache[k]);}
function lastName(inst){return inst?inst.name.split(',')[0].trim().split(' ').pop():'?';}
function dayDisplay(key){const d=STATE.dayClusters.find(x=>x.key===key);return d?d.display:key;}

