function printTimetableOnly(){document.body.classList.add('printing-timetable');window.print();}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-timetable'));

// ============================================================
// SIDEBAR — SETUP GATE + POPULATE
// ============================================================
function refreshSetupGate(){
  const box=document.getElementById('setup-needed-box');
  const fields=document.getElementById('assign-form-fields');
  const missing=[];
  if(!STATE.instructors.length)missing.push('an Instructor');
  if(!STATE.subjects.length)missing.push('a Subject');
  if(!STATE.rooms.length)missing.push('a Room');
  if(!STATE.majors.length)missing.push('a Major');
  if(missing.length){
    box.style.display='block';
    box.innerHTML=`<b>Setup needed</b>Add ${missing.join(', ')} in <b>Manage Data</b> first.`;
    fields.style.display='none';
  }else{
    box.style.display='none';
    fields.style.display='block';
  }
}

function populateSidebar(){
  filterSubjectsBySection();
  document.getElementById('f-day').innerHTML=
    STATE.dayClusters.map(d=>`<option value="${escAttr(d.key)}">${escHtml(d.label)}</option>`).join('');
  document.getElementById('f-timeslot').innerHTML=
    STATE.timeslots.map(t=>`<option value="${escAttr(t.label)}">${escHtml(t.label)}</option>`).join('');
  document.getElementById('f-room').innerHTML=
    STATE.rooms.map(r=>`<option value="${r.id}">${escHtml(r.name)}</option>`).join('');
  refreshSetupGate();
}

function detectYearLevel(section){
  const m=section.match(/\b([1-4])(?:st|nd|rd|th)?\s*[A-Za-z]/i)||section.match(/\b([1-4])\b/);
  return m?parseInt(m[1]):0;
}
function detectProgram(section){
  const s=section.toUpperCase();
  if(s.includes('BEED'))return 'BEED';
  if(s.includes('BSED'))return 'BSED';
  return null;
}

// Step 1: Filter subjects by section (program/year) — no instructor needed
function filterSubjectsBySection(){
  const section = document.getElementById('f-section').value.trim();
  const yearLevel = detectYearLevel(section);
  const program = detectProgram(section);
  const hintEl = document.getElementById('yr-hint');
  const subjSel = document.getElementById('f-subject');
  const YR_NAMES = ['','1st Year','2nd Year','3rd Year','4th Year'];
  const YR = ['','1st Yr','2nd Yr','3rd Yr','4th Yr'];

  if(hintEl){
    if(section){
      const parts=[];
      if(program) parts.push(program);
      if(yearLevel>0) parts.push(YR_NAMES[yearLevel]);
      hintEl.textContent='Filtered: '+(parts.length?parts.join(' + ')+' subjects':'all subjects');
      hintEl.style.display='block';
    }else{
      hintEl.style.display='none';
    }
  }

  const matching = STATE.subjects.filter(s=>{
    if(program&&s.program&&s.program!=='Both'&&s.program!==program)return false;
    if(yearLevel>0&&s.year_level>0&&s.year_level!==yearLevel)return false;
    return true;
  });

  subjSel.innerHTML = matching.length
    ? matching.map(s=>`<option value="${s.id}">${escHtml(s.code)} - ${escHtml(s.descr)} (${s.units} units${s.is_lab?' LAB':''})${s.program&&s.program!=='Both'?' ['+s.program+']':''}${s.year_level>0?' ['+YR[s.year_level]+']':''}</option>`).join('')
    : '<option value="">-- no subjects match this section --</option>';

  filterInstructorsBySubject();
}

// Step 2: Filter instructors by selected subject's major
function filterInstructorsBySubject(){
  const subjId = parseInt(document.getElementById('f-subject').value);
  const subj = STATE.subjects.find(s=>s.id===subjId);
  const instSel = document.getElementById('f-instructor');
  const hintEl = document.getElementById('inst-hint');

  if(!subj){
    instSel.innerHTML = STATE.instructors.map(i=>
      `<option value="${i.id}">${escHtml(i.name)}</option>`
    ).join('');
    if(hintEl) hintEl.style.display='none';
    return;
  }

  // Filter: instructor must have a major/minor matching subject's major_id,
  // OR the subject's major is listed in their allied "can handle" fields
  const qualified = STATE.instructors.filter(i=>
    i.majors.some(m=>m.id===subj.major_id) ||
    (i.can_handle && i.can_handle.some(m=>m.id===subj.major_id))
  );

  if(hintEl){
    const subjMajor = STATE.majors.find(m=>m.id===subj.major_id);
    hintEl.textContent = subjMajor
      ? `Showing instructors with major: ${subjMajor.name}`
      : 'Filtered by subject major';
    hintEl.style.display = 'block';
  }

  instSel.innerHTML = qualified.length
    ? qualified.map(i=>`<option value="${i.id}">${escHtml(i.name)}</option>`).join('')
    : '<option value="">-- no instructor matches this subject --</option>';
}

// Keep old name as alias for backward compat (edit modal etc)
function filterSubjectsByInstructor(){ filterInstructorsBySubject(); }

// ============================================================
// ADD / RESET SCHEDULE
// ============================================================
async function addSchedule(){
  const instructor_id =parseInt(document.getElementById('f-instructor').value);
  const subject_id    =parseInt(document.getElementById('f-subject').value);
  const section       =document.getElementById('f-section').value.trim();
  const num_students  =parseInt(document.getElementById('f-num-students').value)||0;
  const day_key       =document.getElementById('f-day').value;
  const timeslot_label=document.getElementById('f-timeslot').value;
  const room_id       =parseInt(document.getElementById('f-room').value);
  if(!section){showMsg('Please enter a section.',false);return;}
  if(!instructor_id||!subject_id||!room_id){showMsg('Please complete all fields.',false);return;}
  try{
    await apiPost('/schedules',{instructor_id,subject_id,section,num_students,day_key,timeslot_label,room_id});
    showMsg('Schedule added successfully!',true);
    document.getElementById('f-num-students').value='';
    await loadState();renderAll();
    filterSubjectsByInstructor();
    if(window.innerWidth<=640)closeSidebar();
  }catch(e){showMsg(e.message,false);}
}

function showMsg(txt,ok){
  const m=document.getElementById('msg');
  m.textContent=txt;m.className=ok?'ok':'err';m.style.display='block';
  clearTimeout(showMsg._t);
  showMsg._t=setTimeout(()=>m.style.display='none',4500);
}

async function resetSchedules(){
  if(!confirm(`Reset ALL schedules for ${STATE.settings?.semester||'the current semester'}, AY ${STATE.settings?.academic_year||''}? Other semesters' saved schedules are not affected. This cannot be undone.`))return;
  try{await apiDelete('/schedules');await loadState();renderAll();}
  catch(e){showMsg(e.message,false);}
}

// ============================================================
// TIMETABLE
// ============================================================
function renderTimetable(){
  const c=document.getElementById('timetable-grid');
  if(!STATE.schedules.length){
    c.innerHTML=`<div class="no-data">No schedules yet.<br>Use the sidebar to add one${STATE.instructors.length?'':' — add data in <a class="goto-manage" onclick="switchTab(3)">Manage Data</a> first'}.</div>`;
    return;
  }
  let html='';
  for(const dayObj of STATE.dayClusters){
    const ds=STATE.schedules.filter(s=>s.day_key===dayObj.key);
    if(!ds.length)continue;
    const dayRoomIds=[...new Set(ds.map(s=>s.room_id))];
    const dayRooms=STATE.rooms.filter(r=>dayRoomIds.includes(r.id));
    const roomSecs={};
    for(const r of dayRooms)roomSecs[r.id]=[...new Set(ds.filter(s=>s.room_id===r.id).map(s=>s.section))].sort();
    const totalCols=dayRooms.reduce((a,r)=>a+roomSecs[r.id].length,0);

    html+=`<div class="grid-wrap"><div class="grid-header">${escHtml(dayObj.label)}</div>
    <table class="sched-grid"><thead>
    <tr><th class="corner" style="font-size:9px;color:#a8c4e8;">TIME</th>`;
    for(let ri=0;ri<dayRooms.length;ri++){
      html+=`<th class="room-hdr" colspan="${roomSecs[dayRooms[ri].id].length}">${escHtml(dayRooms[ri].name)}</th>`;
      if(ri<dayRooms.length-1)html+=`<th class="room-sep-top"></th>`;
    }
    html+=`</tr></thead><tbody>`;

    let lunchDone=false;
    for(const slot of STATE.timeslots){
      if(!lunchDone&&slot.is_lunch_marker){
        html+=`<tr class="lunch-row"><td class="time-col" style="background:#fff3cd;color:#856404;font-weight:700;">LUNCH</td>
        <td colspan="${totalCols+dayRooms.length-1}">— LUNCH BREAK —</td></tr>`;
        lunchDone=true;
      }
      html+=`<tr><td class="time-col">${escHtml(slot.label)}</td>`;
      for(let ri=0;ri<dayRooms.length;ri++){
        const rm=dayRooms[ri];
        for(const sec of roomSecs[rm.id]){
          const m=ds.find(s=>s.timeslot_label===slot.label&&s.room_id===rm.id&&s.section===sec);
          if(m){
            const inst=getInst(m.instructor_id);
            html+=`<td class="cell-used" style="background:${instColor(m.instructor_id)};cursor:pointer;" onclick="openEditModal(${m.id})" title="Click to edit">
              <strong style="font-size:10px;">${escHtml(m.code)}</strong><br>
              <span style="font-size:9px;color:#777;">${escHtml(m.section)}</span><br>
              <span style="font-size:9px;color:#555;">${escHtml(lastName(inst))}</span>
            </td>`;
          }else html+=`<td class="cell-empty">–</td>`;
        }
        if(ri<dayRooms.length-1)html+=`<td class="room-sep"></td>`;
      }
      html+=`</tr>`;
    }
    html+=`</tbody></table></div>`;
  }
  c.innerHTML=html||'<div class="no-data">No schedules for any configured day cluster.</div>';
}

