// ============================================================
// MANAGE DATA — sidebar nav switch
// ============================================================
function mgSwitch(section, navEl){
  // Update nav active state
  document.querySelectorAll('.mgr-nav-item').forEach(el => el.classList.remove('active'));
  if(navEl) navEl.classList.add('active');
  // Show correct section
  document.querySelectorAll('.mgr-section').forEach(el => el.classList.remove('active'));
  const sec = document.getElementById('mgs-' + section);
  if(sec) sec.classList.add('active');
}

