// ---- Manage: Majors ----
async function addMajor(){} // compat stub — use addMajorType instead
async function addMajorType(type){
  const idMap={'Major':'nm-major','Minor':'nm-minor','Course':'nm-course'};
  const errMap={'Major':'nm-major-err','Minor':'nm-minor-err','Course':'nm-course-err'};
  const inputEl=document.getElementById(idMap[type]);
  const errEl  =document.getElementById(errMap[type]);
  if(!inputEl||!errEl)return;
  const val=inputEl.value.trim();
  errEl.style.display='none';
  if(!val){errEl.textContent='Name required.';errEl.style.display='block';return;}
  try{
    await apiPost('/majors',{name:val,type});
    // If adding a Major, auto-add same name as Minor too
    if(type==='Major'){
      const alreadyMinor=STATE.majors.find(m=>m.name.toLowerCase()===val.toLowerCase()&&m.type==='Minor');
      if(!alreadyMinor) await apiPost('/majors',{name:val,type:'Minor'});
    }
    inputEl.value='';
    await loadState();renderAll();
  }catch(e){errEl.textContent=e.message;errEl.style.display='block';}
}
async function deleteMajor(id){
  try{
    // If deleting a Major, also delete paired Minor with same name
    const major=STATE.majors.find(m=>m.id===id);
    if(major&&major.type==='Major'){
      const paired=STATE.majors.find(m=>m.name.toLowerCase()===major.name.toLowerCase()&&m.type==='Minor');
      if(paired) await apiDelete(`/majors/${paired.id}`);
    }
    await apiDelete(`/majors/${id}`);
    await loadState();renderAll();
  }catch(e){showMsg(e.message,false);}
}

