// ---- Manage: Timeslots ----
function parseTimeLabel(label){
  // Parse "07:00 AM - 08:00 AM" → minutes since midnight for sorting
  const m = label.match(/(\d+):(\d+)\s*(AM|PM)/i);
  if(!m) return 9999;
  let h = parseInt(m[1]), min = parseInt(m[2]);
  const period = m[3].toUpperCase();
  if(period === 'PM' && h !== 12) h += 12;
  if(period === 'AM' && h === 12) h = 0;
  return h * 60 + min;
}
async function addTimeslot(){
  const label=document.getElementById('nts-label').value.trim();
  const is_lunch_marker=document.getElementById('nts-lunch').checked;
  const err=document.getElementById('nts-err');err.style.display='none';
  if(!label)return;
  // Compute sort_order from time so it slots in correct chronological position
  const sort_order = parseTimeLabel(label);
  try{
    await apiPost('/timeslots',{label,is_lunch_marker,sort_order});
    document.getElementById('nts-label').value='';
    document.getElementById('nts-lunch').checked=false;
    await loadState();renderAll();
  }catch(e){err.textContent=e.message;err.style.display='block';}
}
async function deleteTimeslot(id){
  try{await apiDelete(`/timeslots/${id}`);await loadState();renderAll();}
  catch(e){showMsg(e.message,false);}
}

