const tabBtns=document.querySelectorAll('.tab-btn');
const panelDivs=document.querySelectorAll('.panel');
function switchTab(n){
  tabBtns.forEach((b,i)=>b.classList.toggle('active',i===n));
  panelDivs.forEach((p,i)=>p.classList.toggle('active',i===n));
  if(n===1)renderClassProgram();
  if(n===2)renderWorkload();
  if(n===3)renderManageData();
}

function renderAll(){
  populateSidebar();renderTimetable();
  populateClassProgramSelector();populateWorkloadSelector();renderManageData();
  const active=[...panelDivs].findIndex(p=>p.classList.contains('active'));
  if(active===1)renderClassProgram();
  if(active===2)renderWorkload();
}

